import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import process from 'node:process';

function parseArguments(values){
  const options=new Map();
  for(let index=2;index<values.length;++index){const name=values[index];if(!name.startsWith('--')||index+1>=values.length)throw new Error(`Invalid argument: ${name}`);options.set(name.slice(2),values[++index]);}
  const integer=(name,fallback,minimum,maximum)=>{const value=Number(options.get(name)??fallback);if(!Number.isInteger(value)||value<minimum||value>maximum)throw new Error(`Invalid --${name}`);return value;};
  return {endpoint:options.get('endpoint')??'http://127.0.0.1:9222',baseUrl:options.get('base-url')??'http://127.0.0.1:8876/',output:resolve(options.get('output')??'edge-cpu-result.json'),
    machine:options.get('machine')??process.env.COMPUTERNAME??'unknown',architecture:options.get('architecture')??process.arch,repetitions:integer('repetitions',3,1,10),frames:integer('frames',1800,600,10000),
    warmupFrames:integer('warmup-frames',300,0,5000),width:integer('width',1920,320,7680),height:integer('height',1080,240,4320),timeoutMs:integer('timeout-ms',900000,30000,3600000)};
}
class CdpConnection{
  constructor(url){this.nextId=1;this.pending=new Map();this.socket=new WebSocket(url);}
  async open(){await new Promise((done,reject)=>{this.socket.addEventListener('open',done,{once:true});this.socket.addEventListener('error',()=>reject(new Error('CDP connection failed')),{once:true});});this.socket.addEventListener('message',event=>{const message=JSON.parse(event.data);if(!message.id||!this.pending.has(message.id))return;const pending=this.pending.get(message.id);this.pending.delete(message.id);clearTimeout(pending.timer);message.error?pending.reject(new Error(message.error.message)):pending.done(message.result);});this.socket.addEventListener('close',()=>{for(const pending of this.pending.values()){clearTimeout(pending.timer);pending.reject(new Error('CDP connection closed'));}this.pending.clear();});}
  request(method,params={},sessionId,timeoutMs=1200000){const id=this.nextId++;return new Promise((done,reject)=>{const timer=setTimeout(()=>{this.pending.delete(id);reject(new Error(`CDP request timed out: ${method}`));},timeoutMs);this.pending.set(id,{done,reject,timer});this.socket.send(JSON.stringify(sessionId?{id,method,params,sessionId}:{id,method,params}));});}
  close(){this.socket.close();}
}
const delay=milliseconds=>new Promise(done=>setTimeout(done,milliseconds));
async function connect(endpoint){const response=await fetch(new URL('/json/version',endpoint));if(!response.ok)throw new Error(`CDP version HTTP ${response.status}`);const version=await response.json();const endpointUrl=new URL(endpoint);const socketUrl=new URL(version.webSocketDebuggerUrl);socketUrl.protocol=endpointUrl.protocol==='https:'?'wss:':'ws:';socketUrl.hostname=endpointUrl.hostname;socketUrl.port=endpointUrl.port;const connection=new CdpConnection(socketUrl);await connection.open();return{connection,version};}
async function waitForPage(connection,sessionId,url,timeoutMs){const deadline=Date.now()+timeoutMs;while(Date.now()<deadline){try{const check=await connection.request('Runtime.evaluate',{expression:`location.href === ${JSON.stringify(url)} && document.readyState !== 'loading'`,returnByValue:true},sessionId);if(check.result.value===true)return;}catch{}await delay(100);}throw new Error('Page navigation timed out');}
async function captureRun(connection,options,repeat){
  console.log(`Edge CPU r${repeat}: create context`);
  const {browserContextId}=await connection.request('Target.createBrowserContext',{disposeOnDetach:true});let targetId;
  try{
    console.log(`Edge CPU r${repeat}: create target`);
    ({targetId}=await connection.request('Target.createTarget',{url:'about:blank',browserContextId}));await connection.request('Target.activateTarget',{targetId});
    const {sessionId}=await connection.request('Target.attachToTarget',{targetId,flatten:true});await connection.request('Runtime.enable',{},sessionId);await connection.request('Page.enable',{},sessionId);
    await connection.request('Emulation.setDeviceMetricsOverride',{width:options.width,height:options.height+36,deviceScaleFactor:1,mobile:false,screenWidth:options.width,screenHeight:options.height+36},sessionId);
    const url=new URL('DayScene.html',options.baseUrl);url.search=new URLSearchParams({scene:'1',width:String(options.width),height:String(options.height),postProcessMode:'compute',shaderFlow:'wgsl',culling:'full',logLevel:'info',profile:'1',profileFrames:String(options.frames),benchmark:'1',capture:`cpu-${repeat}-${Date.now()}`});
    await connection.request('Page.navigate',{url:url.href},sessionId);await waitForPage(connection,sessionId,url.href,options.timeoutMs);console.log(`Edge CPU r${repeat}: profiling`);
    const completed=await connection.request('Runtime.evaluate',{expression:`new Promise(resolve=>{const deadline=Date.now()+${options.timeoutMs};const inspect=()=>{const state=window.t850||{};if(state.state==='failed')resolve({ok:false,error:state.lastError?.message||state.errors?.at(-1)||'Browser failed',logs:state.logs?.slice(-12)||[]});else if(state.telemetry)resolve({ok:true,renderSize:state.renderSize,errors:state.errors||[]});else if(Date.now()>=deadline)resolve({ok:false,error:'CPU profile timed out',logs:state.logs?.slice(-12)||[]});else setTimeout(inspect,100);};inspect();})`,awaitPromise:true,returnByValue:true},sessionId);
    const state=completed.result.value;console.log(`Edge CPU r${repeat}: profile complete`);if(!state?.ok)throw new Error(`${state?.error}\n${(state?.logs??[]).join('\n')}`);if(state.errors.length)throw new Error(state.errors.join('\n'));if(state.renderSize?.[0]!==options.width||state.renderSize?.[1]!==options.height)throw new Error(`Render size mismatch: ${state.renderSize}`);
    const lengthResult=await connection.request('Runtime.evaluate',{expression:'window.__t850CpuTelemetryJson=JSON.stringify(window.t850.telemetry);window.__t850CpuTelemetryJson.length',returnByValue:true},sessionId);const length=lengthResult.result.value;const chunkSize=262144;let telemetryText='';for(let offset=0;offset<length;offset+=chunkSize){const chunk=await connection.request('Runtime.evaluate',{expression:`window.__t850CpuTelemetryJson.slice(${offset},${Math.min(offset+chunkSize,length)})`,returnByValue:true},sessionId);telemetryText+=chunk.result.value;}await connection.request('Runtime.evaluate',{expression:'delete window.__t850CpuTelemetryJson',returnByValue:true},sessionId);const telemetry=JSON.parse(telemetryText);const measured=telemetry.frames.filter(frame=>!frame.startup&&frame.detailed!==false);const steady=measured.filter(frame=>frame.frame>=options.warmupFrames&&frame.frame<options.frames);
    if(telemetry.version!==2||telemetry.droppedRecords!==0||telemetry.unfinishedWriters!==0||measured.length!==options.frames||steady.length!==options.frames-options.warmupFrames)throw new Error('Incomplete browser CPU telemetry');
    const directory=resolve(dirname(options.output),`runs/edge-r${repeat}`);await mkdir(directory,{recursive:true});await writeFile(resolve(directory,'telemetry.json'),JSON.stringify(telemetry));
    return{cell:'edge',repeat,telemetry:`runs/edge-r${repeat}/telemetry.json`,frames:options.frames,steadyFrames:steady.length,renderSize:state.renderSize,url:url.href};
  }finally{if(targetId)await connection.request('Target.closeTarget',{targetId}).catch(()=>{});await connection.request('Target.disposeBrowserContext',{browserContextId}).catch(()=>{});}
}
const options=parseArguments(process.argv);if(options.warmupFrames>=options.frames)throw new Error('warmup-frames must be less than frames');await mkdir(dirname(options.output),{recursive:true});
const result={schema:1,startedUtc:new Date().toISOString(),passed:false,machine:options.machine,architecture:options.architecture,repetitions:options.repetitions,frames:options.frames,warmupFrames:options.warmupFrames,width:options.width,height:options.height,postProcessMode:'compute',shaderFlow:'wgsl',runs:[]};let connection;
try{console.log('Edge CPU: runtime identity');const identityResponse=await fetch(new URL('__t850',options.baseUrl));if(!identityResponse.ok)throw new Error(`Runtime identity HTTP ${identityResponse.status}`);result.runtimeIdentity=(await identityResponse.json()).identity;console.log('Edge CPU: connect CDP');const connected=await connect(options.endpoint);connection=connected.connection;result.cdpVersion=connected.version;for(let repeat=1;repeat<=options.repetitions;++repeat)result.runs.push(await captureRun(connection,options,repeat));result.passed=true;}catch(error){result.failure=error?.stack??String(error);}finally{connection?.close();result.completedUtc=new Date().toISOString();await writeFile(options.output,JSON.stringify(result,null,2)+'\n');}
if(!result.passed)throw new Error(result.failure);console.log(`PASS: Edge CPU overhead matrix at ${options.output}`);